import{_ as t,g as n,e as a,a4 as i}from"./chunks/framework.CEYJDsBW.js";const b=JSON.parse('{"title":"BlockEntityEvent","description":"","frontmatter":{},"headers":[],"relativePath":"en/anvilcraft/26.1/events/block-entity-event.md","filePath":"en/anvilcraft/26.1/events/block-entity-event.md"}'),o={name:"en/anvilcraft/26.1/events/block-entity-event.md"};function r(c,e,d,l,v,s){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="blockentityevent" tabindex="-1">BlockEntityEvent <a class="header-anchor" href="#blockentityevent" aria-label="Permalink to &quot;BlockEntityEvent&quot;">​</a></h1><p>When maintaining a server-side index of add-on devices, subscribe to <code>ServerLoad</code> to register the instance carried by the event and <code>ServerUnload</code> to remove that same instance. The load event is posted in <code>LevelChunk.setBlockEntity</code> right before the instance is written to the map, so immediately querying by coordinates may still return the old object. Neither sub-event supports cancellation.</p><p>In addition to explicit removal, unload notifications can come from replacing an old instance or cleaning up invalid caches. When keying indexes by dimension and coordinates, compare instances before removing to avoid an old notification deleting a new entry. This tracks the block entity map lifecycle, so receiving an unload does not by itself mean a player broke the block. <a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/mixin/LevelChunkMixin.java" target="_blank" rel="noreferrer">Chunk injection site</a></p><table tabindex="0"><thead><tr><th>Event Type</th><th>Construction Site</th></tr></thead><tbody><tr><td><code>BlockEntityEvent</code></td><td>No direct construction call site under this name in this commit</td></tr><tr><td><code>BlockEntityEvent.ServerLoad</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/mixin/LevelChunkMixin.java#L70" target="_blank" rel="noreferrer"><code>LevelChunkMixin:70</code></a></td></tr><tr><td><code>BlockEntityEvent.ServerUnload</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/mixin/LevelChunkMixin.java#L83" target="_blank" rel="noreferrer"><code>LevelChunkMixin:83</code></a>, <a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/mixin/LevelChunkMixin.java#L102" target="_blank" rel="noreferrer"><code>LevelChunkMixin:102</code></a>, <a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/mixin/LevelChunkMixin.java#L119" target="_blank" rel="noreferrer"><code>LevelChunkMixin:119</code></a></td></tr></tbody></table>',4)])])}const f=t(o,[["render",r]]);export{b as __pageData,f as default};
